def bubble_sort(a: list[int]) -> None:
    n = len(a)
    for pass_i in range(n - 1):
        swapped = False
        for j in range(0, n - 1 - pass_i):
            if a[j] > a[j + 1]:
                a[j], a[j + 1] = a[j + 1], a[j]
                swapped = True
        if not swapped:
            break
